def find_duplicates(arr: list[int]) -> list[int]:
    """Find all duplicate elements in an array using O(1) extra space.

    Uses index marking: for each element, negate the value at index abs(element).
    If that value is already negative, the element is a duplicate.

    Constraints:
        - Elements must be non-negative integers.
        - All elements must be in range [0, len(arr) - 1].

    Time: O(n), Space: O(1) extra (modifies input in-place).
    """
    duplicates = []
    for num in arr:
        idx = abs(num)
        if arr[idx] < 0:
            duplicates.append(idx)
        else:
            arr[idx] = -arr[idx]
    # Restore array to original values
    for i in range(len(arr)):
        arr[i] = abs(arr[i])
    return duplicates


def deep_merge(base: dict, override: dict) -> dict:
    """Recursively merge `override` into `base`, returning a new dict.

    Nested dicts are merged; all other values are overwritten by `override`.
    """
    result = base.copy()
    for key, value in override.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = deep_merge(result[key], value)
        else:
            result[key] = value
    return result


