def test_find_duplicates():
    # Basic cases
    assert find_duplicates([1, 2, 3, 4]) == []
    assert find_duplicates([1, 2, 3, 1]) == [1]
    assert sorted(find_duplicates([1, 2, 2, 3, 3, 4])) == [2, 3]

    # All same element
    assert sorted(find_duplicates([0, 0, 0, 0])) == [0]

    # Single element
    assert find_duplicates([0]) == []

    # Multiple duplicates of same value
    assert sorted(find_duplicates([2, 1, 2, 1, 2])) == [1, 2]

    # Edge: empty array
    assert find_duplicates([]) == []

    # Verify array is restored after the call
    arr = [3, 1, 2, 3]
    find_duplicates(arr)
    assert arr == [3, 1, 2, 3]

    print("find_duplicates: all tests passed")


def test_deep_merge():
    # Simple flat merge
    assert deep_merge({"a": 1}, {"b": 2}) == {"a": 1, "b": 2}

    # Override wins
    assert deep_merge({"a": 1}, {"a": 2}) == {"a": 2}

    # Nested merge
    base = {"x": {"a": 1, "b": 2}, "y": 10}
    over = {"x": {"b": 3, "c": 4}}
    assert deep_merge(base, over) == {"x": {"a": 1, "b": 3, "c": 4}, "y": 10}

    # Deeply nested
    base = {"a": {"b": {"c": 1}}}
    over = {"a": {"b": {"d": 2}}}
    assert deep_merge(base, over) == {"a": {"b": {"c": 1, "d": 2}}}

    # Type conflict: dict overwritten by non-dict
    assert deep_merge({"a": {"x": 1}}, {"a": 42}) == {"a": 42}

    # Non-dict overwritten by dict
    assert deep_merge({"a": 42}, {"a": {"x": 1}}) == {"a": {"x": 1}}

    # Empty dicts
    assert deep_merge({}, {"a": 1}) == {"a": 1}
    assert deep_merge({"a": 1}, {}) == {"a": 1}
    assert deep_merge({}, {}) == {}

    # Originals not mutated
    base = {"a": {"x": 1}}
    over = {"a": {"y": 2}}
    result = deep_merge(base, over)
    assert base == {"a": {"x": 1}}
    assert over == {"a": {"y": 2}}
    assert result == {"a": {"x": 1, "y": 2}}

    print("deep_merge: all tests passed")


if __name__ == "__main__":
    test_find_duplicates()
    test_deep_merge()
